mapper.select:
WITH ranked AS ( SELECT u.id AS userId, u.username AS username, u.avatar_url AS avatarUrl, u.bio AS bio, u.roles AS roles, COUNT(DISTINCT CASE WHEN s.status = 'ACCEPTED' THEN s.question_id END) AS solvedCount, COUNT(s.id) AS totalSubmissions, COUNT(CASE WHEN s.status = 'ACCEPTED' THEN 1 END) AS acSubmissions, ROUND(COUNT(CASE WHEN s.status = 'ACCEPTED' THEN 1 END) * 100.0 / NULLIF(COUNT(s.id), 0), 1) AS acceptRate, 0 AS totalScore, MAX(CASE WHEN s.status = 'ACCEPTED' THEN s.created_at END) AS lastAcceptedAt, ROW_NUMBER() OVER ( ORDER BY COUNT(DISTINCT CASE WHEN s.status = 'ACCEPTED' THEN s.question_id END) DESC, COUNT(CASE WHEN s.status = 'ACCEPTED' THEN 1 END) DESC, COUNT(s.id) ASC, MAX(CASE WHEN s.status = 'ACCEPTED' THEN s.created_at END) ASC, u.id ASC ) AS `rank` FROM `user` u LEFT JOIN `submission` s ON u.id = s.user_id WHERE u.status = 1 GROUP BY u.id, u.username, u.avatar_url, u.bio, u.roles HAVING totalSubmissions > 0 ) SELECT * FROM ranked
username LIKE CONCAT('%', #{keyword}, '%')
ORDER BY `rank` ASC LIMIT #{offset}, #{size}

WITH ranked AS ( SELECT u.id AS userId, u.username AS username, u.avatar_url AS avatarUrl, u.bio AS bio, u.roles AS roles, COUNT(DISTINCT CASE WHEN s.status = 'ACCEPTED' THEN s.question_id END) AS solvedCount, COUNT(s.id) AS totalSubmissions, COUNT(CASE WHEN s.status = 'ACCEPTED' THEN 1 END) AS acSubmissions, ROUND(COUNT(CASE WHEN s.status = 'ACCEPTED' THEN 1 END) * 100.0 / NULLIF(COUNT(s.id), 0), 1) AS acceptRate, 0 AS totalScore, MAX(CASE WHEN s.status = 'ACCEPTED' THEN s.created_at END) AS lastAcceptedAt, ROW_NUMBER() OVER ( ORDER BY COUNT(DISTINCT CASE WHEN s.status = 'ACCEPTED' THEN s.question_id END) DESC, COUNT(CASE WHEN s.status = 'ACCEPTED' THEN 1 END) DESC, COUNT(s.id) ASC, MAX(CASE WHEN s.status = 'ACCEPTED' THEN s.created_at END) ASC, u.id ASC ) AS `rank` FROM `user` u LEFT JOIN `db_submission` s ON u.id = s.user_id WHERE u.status = 1 GROUP BY u.id, u.username, u.avatar_url, u.bio, u.roles HAVING totalSubmissions > 0 ) SELECT * FROM ranked
username LIKE CONCAT('%', #{keyword}, '%')
ORDER BY `rank` ASC LIMIT #{offset}, #{size}

WITH ranked AS ( SELECT u.id AS userId, u.username AS username, u.avatar_url AS avatarUrl, u.bio AS bio, u.roles AS roles, COUNT(DISTINCT CASE WHEN s.correct = 1 THEN s.question_id END) AS solvedCount, COALESCE(SUM(s.score), 0) AS totalScore, COUNT(s.id) AS totalSubmissions, COUNT(CASE WHEN s.correct = 1 THEN 1 END) AS acSubmissions, ROUND(COUNT(CASE WHEN s.correct = 1 THEN 1 END) * 100.0 / NULLIF(COUNT(s.id), 0), 1) AS acceptRate, MAX(CASE WHEN s.correct = 1 THEN s.created_at END) AS lastAcceptedAt, ROW_NUMBER() OVER ( ORDER BY COUNT(DISTINCT CASE WHEN s.correct = 1 THEN s.question_id END) DESC, COALESCE(SUM(s.score), 0) DESC, COUNT(CASE WHEN s.correct = 1 THEN 1 END) DESC, COUNT(s.id) ASC, MAX(CASE WHEN s.correct = 1 THEN s.created_at END) ASC, u.id ASC ) AS `rank` FROM `user` u LEFT JOIN `objective_submission` s ON u.id = s.user_id WHERE u.status = 1 GROUP BY u.id, u.username, u.avatar_url, u.bio, u.roles HAVING totalSubmissions > 0 ) SELECT * FROM ranked
username LIKE CONCAT('%', #{keyword}, '%')
ORDER BY `rank` ASC LIMIT #{offset}, #{size}
